import ast, sys, pathlib
files = ["brave.py","duckduckgo.py","qwant.py","startpage.py","yandex.py","base.py","multi.py"]
for f in files:
    p = pathlib.Path(r"C:\Users\spay\Documents\PR\zettelkasten\research_agent\search")/f
    tree = ast.parse(p.read_text(encoding="utf-8"))
    bound=set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names: bound.add((a.asname or a.name).split(".")[0])
        elif isinstance(n, ast.ImportFrom):
            for a in n.names: bound.add(a.asname or a.name)
        elif isinstance(n, ast.Assign):
            for t in n.targets:
                if isinstance(t, ast.Name): bound.add(t.id)
    uses = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
    print(f, "| logger bound:", "logger" in bound, "| logger used:", "logger" in uses)
'@; $py | Out-File -Encoding utf8 "$env:TEMP\chk.py"; python "$env:TEMP\chk.py"","description":"AST check for logger binding in search modules"}
